where char_length(v.title) between 2 and 120
  and char_length(v.website) between 8 and 500
  and (v.phone = '' or char_length(v.phone) <= 40)
  and not exists (
    select 1
    from public.pins p
    where p.status = 'published'
      and st_dwithin(p.coords, st_setsrid(st_makepoint(v.lng, v.lat), 4326)::geography, 40)
  );
